import com.greascent.app.StudyEngine;
import java.io.*;
import java.util.*;
public class EngineTests {
    static int assertions=0;
    static void check(boolean ok,String message){assertions++;if(!ok)throw new AssertionError(message);}
    static List<StudyEngine.Word> words(int n){List<StudyEngine.Word> ws=new ArrayList<>();for(int i=0;i<n;i++)ws.add(new StudyEngine.Word("w"+i,"term"+i,"source definition "+i,i));return ws;}
    static StudyEngine fresh(int n){return new StudyEngine(words(n),new StudyEngine.State());}
    public static void main(String[] args)throws Exception{
        if(args.length>0&&args[0].equals("real")){
            List<StudyEngine.Word> actual=new ArrayList<>();for(String line:java.nio.file.Files.readAllLines(new File(args[1]).toPath(),java.nio.charset.StandardCharsets.UTF_8)){String[] cols=line.split("\t",-1);StudyEngine.Word w=new StudyEngine.Word(cols[0],cols[1],cols[2],Integer.parseInt(cols[3]));w.families.addAll(Arrays.asList(cols[4].split(",")));actual.add(w);}
            StudyEngine e=new StudyEngine(actual,new StudyEngine.State());check(actual.size()==959,"real corpus loaded");for(StudyEngine.Word w:actual){List<StudyEngine.Word> options=e.options(w.id);check(options.size()==4,"real corpus has four valid options");check(options.contains(w),"real corpus includes correct word");for(StudyEngine.Word o:options){check(e.byId.get(o.id)==o,"real options only contain source objects");if(o!=w)check(Collections.disjoint(o.families,w.families),"real distractors exclude linked families");}}
            System.out.println("Real-source quiz generation: "+assertions+" assertions passed across 959 words");return;
        }
        if(args.length>0){File f=new File(args[1]);if(args[0].equals("write")){StudyEngine e=fresh(46);e.startBlock(1,1);e.s.theme="light";e.s.session.cardIndex=4;e.s.session.draft="half typed";e.s.timers.put(1,345678L);e.s.officialSelection.add("B");e.s.officialFeedback=true;e.confidence("w0",true,false);e.record("w0","term0","Spelling recall",true,false,1,"");StudyEngine.save(e.s,f);}else{StudyEngine e=new StudyEngine(words(46),StudyEngine.load(f));check(e.s.theme.equals("light"),"theme persisted");check(e.s.session.cardIndex==4,"card index persisted");check(e.s.session.draft.equals("half typed"),"draft persisted");check(e.s.timers.get(1)==345678L,"timer persisted");check(e.s.attempts.size()==1&&e.s.due.size()==1,"history and due persisted");check(e.s.officialSelection.contains("B")&&e.s.officialFeedback,"official attempt state persisted");System.out.println("Fresh process reload: "+assertions+" assertions passed");}return;}
        StudyEngine e=fresh(959);
        check(e.dayCount()==22,"22 days");check(e.day(22).size()==14,"partial last day");check(e.block(22,1).size()==14&&e.block(22,2).isEmpty(),"partial block");
        HashSet<String> assigned=new HashSet<>();for(int d=1;d<=22;d++)for(int b=1;b<=3;b++)for(StudyEngine.Word w:e.block(d,b))check(assigned.add(w.id),"unique allocation");check(assigned.size()==959,"no missing IDs");
        e.confidence("w0",true,false);check(e.s.due.get("w0").day==3,"confident confirmation N+2");check(e.dueNow().isEmpty(),"not forced next day");
        e.grade("w0",false,false,false);check(e.s.due.get("w0").day==2,"wrong overrides confident");e.grade("w0",true,false,true);check(e.s.due.get("w0").day==2,"immediate retry remains next-day");
        e.s.studyDay=2;e.grade("w0",false,false,false);check(e.s.due.get("w0").day==3,"repeated wrong");e.s.studyDay=3;e.grade("w0",true,false,false);check(e.s.due.get("w0").day==5,"correct after errors confirm day5");
        e.record("w0","term0","Scheduled review",true,false,3,"");e.s.studyDay=4;check(e.dueNow().isEmpty(),"gap day4");check(e.historyStatus("w0",4).startsWith("Not scheduled"),"history gap explicit");e.s.studyDay=5;e.grade("w0",true,false,false);check(!e.s.due.containsKey("w0")&&e.s.mastered.contains("w0"),"correct confirm retires");check(e.s.attempts.size()==1,"history survives retirement");
        e=fresh(45);e.confidence("w1",true,false);e.s.studyDay=3;e.grade("w1",false,false,false);check(e.s.due.get("w1").day==4,"failed confirmation next day");
        e=fresh(46);e.startBlock(1,1);check(e.s.session.coreCount==15,"15 core questions");check(!e.canQuiz(),"core gated on flashcards");for(String id:e.s.session.cards)e.confidence(id,true,false);check(e.canQuiz(),"core unlocked");e.beginQuiz();e.answer("wrong");check(e.s.session.queue.size()==16,"wrong queued after cores");check(e.s.session.queue.get(15).equals("w0"),"retry never displaces core");check(e.total()==1&&e.count(e.day(1))==1,"counts require seen+core answer");check(e.s.due.get("w0").day==2,"wrong due next day");e.nextQuestion();
        for(int i=1;i<15;i++){e.answer("term"+i);e.nextQuestion();}check(e.s.session.index==15,"all cores first");check(e.format().equals("Spelling recall"),"MCQ retry switches to spelling");e.answer("term0");check(e.s.due.get("w0").day==2,"correct retry does not cancel due");check(e.total()==15,"retry no progress inflation");
        StudyEngine mixed=fresh(45);mixed.confidence("w0",true,false);mixed.s.coreDone.add("w0");mixed.startBlock(1,1);mixed.beginQuiz();mixed.answer("wrong");mixed.s.session.index=15;mixed.s.session.feedback=false;int mixedDue=mixed.s.due.get("w0").day;mixed.answer("wrong again");check(mixed.s.due.get("w0").day==mixedDue,"retry of already-completed item stays replay in mixed session");
        int old=e.total();e.s.studyDay=2;e.startBlock(1,1);check(e.s.session.mode.equals("replay"),"old day is replay");e.beginQuiz();int due=e.s.due.get("w0").day;e.answer("wrong");e.nextQuestion();check(e.total()==old&&e.s.due.get("w0").day==due,"replay preserves unique+schedule");check(e.s.attempts.get(e.s.attempts.size()-1).replay,"replay marked in history");check(e.s.studyDay==2,"replay no clock rewind");
        e=fresh(46);e.confidence("w45",true,false);e.s.coreDone.add("w45");check(e.total()==1&&e.count(e.day(1))==0&&e.count(e.day(2))==1,"daily separate overall");
        check(StudyEngine.spelling("  Term0 ","term0"),"harmless input normalized");check(!StudyEngine.spelling("term 0","term0"),"actual spelling error rejected");
        e=fresh(80);for(StudyEngine.Word w:e.words){List<StudyEngine.Word> opts=e.options(w.id);check(opts.size()==4,"four options");for(StudyEngine.Word o:opts)check(e.byId.containsKey(o.id),"distractor source only");}
        e=fresh(1);check(e.options("w0").size()==1,"missing distractors safe");check(e.day(99).isEmpty(),"empty days safe");
        e=fresh(35);e.words.get(17).families.add("F1");e.words.get(0).families.add("F1");check(!e.options("w0").contains(e.words.get(17)),"same-family distractor excluded");
        e=fresh(45);e.startBlock(1,1);long timer=e.s.timers.get(1);e.s.timers.put(1,123456L);e.startBlock(1,2);check(e.s.timers.get(1)==123456L,"switching blocks never resets timer");
        e.consumeFocus(1000,true);check(e.s.timers.get(1)==122456L,"foreground consumes elapsed focus time");e.consumeFocus(99999,false);check(e.s.timers.get(1)==122456L,"background does not consume focus time");check(e.consumeFocus(999999,true)&&e.s.timers.get(1)==0,"countdown clamps at zero");e.startBlock(1,3);check(e.s.timers.get(1)==0,"zero timer never resets");e.confidence("w30",true,false);check(e.s.seen.contains("w30"),"study remains functional after timer zero");
        e=fresh(90);e.startBlock(1,1);e.s.session.cardIndex=7;e.startBlock(1,2);e.s.session.cardIndex=3;e.startReview();e.startBlock(1,1);check(e.s.session.cardIndex==7,"return from reviews restores original block card");e.startBlock(1,2);check(e.s.session.cardIndex==3,"independent in-flight block state retained");
        e=fresh(45);e.startBlock(1,1);for(String id:e.s.session.cards)e.confidence(id,true,false);e.beginQuiz();e.answer("wrong");java.io.File inflight=new java.io.File("build/tests/inflight.bin");StudyEngine.save(e.s,inflight);StudyEngine restored=new StudyEngine(words(45),StudyEngine.load(inflight));check(restored.s.session.quiz&&restored.s.session.feedback&&!restored.s.session.correct,"quiz feedback persisted");check(restored.s.session.queue.size()==16&&restored.s.session.retried.contains("w0"),"retry queue persisted");check(restored.total()==1,"progress persisted");
        File corrupt=new File("build/tests/corrupt.bin");try(FileOutputStream out=new FileOutputStream(corrupt)){out.write(new byte[]{1,2,3});}boolean corruptionRejected=false;try{StudyEngine.load(corrupt);}catch(IOException expected){corruptionRejected=true;}check(corruptionRejected&&corrupt.length()==3,"corrupt state rejected without deleting it");
        StudyEngine.State unknown=new StudyEngine.State();unknown.schema=99;boolean rejected=false;try{new StudyEngine(words(1),unknown);}catch(IllegalStateException expected){rejected=true;}check(rejected,"future schema protected");
        e=fresh(45);e.startBlock(1,1);for(int index=0;index<15;index++){e.jumpCard(index);check(e.s.session.cardIndex==index&&e.current().equals("w"+index),"numbered selector visits exact source item");}check(e.total()==0&&e.s.seen.isEmpty()&&e.s.attempts.isEmpty(),"browsing numbered words never records learning or guesses");e.jumpCard(15);check(e.s.session.cardIndex==14,"out-of-range position ignored");e.beginQuiz();e.jumpCard(0);check(e.s.session.cardIndex==14,"card jumping cannot alter quiz state");
        ArrayList<ArrayList<String>> groups=new ArrayList<>();groups.add(new ArrayList<>(Arrays.asList("A","B","C")));groups.add(new ArrayList<>(Arrays.asList("D","E","F")));groups.add(new ArrayList<>(Arrays.asList("G","H","I")));Set<String> selected=new HashSet<>();StudyEngine.selectChoice(selected,"multiBlank",groups,"A",true);StudyEngine.selectChoice(selected,"multiBlank",groups,"F",true);StudyEngine.selectChoice(selected,"multiBlank",groups,"H",true);check(StudyEngine.selectionComplete(selected,3,groups),"triple blank one answer per group is complete");StudyEngine.selectChoice(selected,"multiBlank",groups,"B",true);check(!selected.contains("A")&&selected.containsAll(Arrays.asList("B","F","H")),"changing blank1 preserves blank2 and blank3");StudyEngine.selectChoice(selected,"multiBlank",groups,"B",false);check(!StudyEngine.selectionComplete(selected,3,groups),"missing blank selection rejected");
        ArrayList<ArrayList<String>> doubles=new ArrayList<>(groups.subList(0,2));selected.clear();StudyEngine.selectChoice(selected,"multiBlank",doubles,"B",true);StudyEngine.selectChoice(selected,"multiBlank",doubles,"F",true);check(StudyEngine.selectionComplete(selected,2,doubles),"double blank independent selections complete");selected.clear();selected.add("A");selected.add("B");check(!StudyEngine.selectionComplete(selected,2,doubles),"two choices in one blank never satisfy two-blank question");
        selected.clear();StudyEngine.selectChoice(selected,"multiSelect",Collections.emptyList(),"A",true);StudyEngine.selectChoice(selected,"multiSelect",Collections.emptyList(),"F",true);check(StudyEngine.selectionComplete(selected,2,Collections.emptyList()),"SE two choices remain independent from blank count");StudyEngine.selectChoice(selected,"pair",Collections.emptyList(),"C",true);check(selected.equals(new HashSet<>(Arrays.asList("C"))),"legacy pair is one selection for both blanks");
        check(StudyEngine.formatMatches("TC",3,"3")&&!StudyEngine.formatMatches("SE",1,"1"),"format filter distinguishes blank count from SE answer count");check(StudyEngine.formatMatches("Legacy TC",2,"2")&&StudyEngine.formatMatches("SE",1,"SE"),"legacy double and SE filters supported");
        StudyEngine.State oldState=new StudyEngine.State();oldState.practiceFilter=null;check(new StudyEngine(words(1),oldState).s.practiceFilter.equals("all"),"older serialized state gets safe default filter");
        System.out.println("Study engine: "+assertions+" assertions passed");
    }
}
